def block(t):return 'blocks('+repr(t)+')\n'
def replace_literal_assignment(name,text):
    global s
    for node in ast.parse(s).body:
        if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id==name for t in node.targets):
            lines=s.splitlines(keepends=True);lines[node.lineno-1:node.end_lineno]=[name+'='+repr(text)+'\n'];s=''.join(lines);return
    raise ValueError(name)
resumen='¿La actualización 3D de Vp mejora la predicción de tiempos P frente a un control 1D con relocalización y correcciones de estación? Evaluamos 3734 eventos identificados por el Servicio Geológico Colombiano mediante reserva por eventos, refinamiento del cálculo directo, dameros no lineales y reservas regionales. El modelo 3D reduce el error de entrenamiento, pero su RMS reservado de 1,551 s supera los 1,527 s del control 1D; la reserva regional confirma esa desventaja. Ninguno de los tres medios evaluados cumple la tolerancia de refinamiento y los dameros de ±3 % y ±8 % presentan correlaciones de recuperación de 0,044 y 0,095. En los sintéticos, el RMS hipocentral aumenta desde 4,95 km hasta 14,71 y 16,57 km. La asociación de estáticas con elevación aparece en el control 1D y es prácticamente nula en el 3D. Las superficies sísmicas B-spline se documentan como construcciones geométricas. Los resultados distinguen ajuste interno, predicción y recuperación, y no validan las amplitudes de Vp ni interfaces de placa.'
abstract='Does updating Vp in three dimensions improve P arrival predictions over a 1D control with relocation and station corrections? We evaluate 3734 events identified by the Colombian Geological Survey using event holdouts, forward grid refinement, nonlinear checkerboards and regional holdouts. The 3D model reduces training error, but its held-out RMS of 1.551 s exceeds the 1D control value of 1.527 s; regional validation confirms this disadvantage. None of the three tested media meets the refinement tolerance, and ±3% and ±8% nonlinear checkerboards yield recovery correlations of 0.044 and 0.095. Synthetic hypocentral RMS increases from 4.95 km to 14.71 and 16.57 km. Station elevation is associated with statics in the 1D control, whereas the association is negligible in 3D. Seismic B-spline surfaces are documented as geometric constructions. These results distinguish internal fit, prediction and recovery, and do not validate Vp amplitudes or plate interfaces.'
replace_literal_assignment('resumen',resumen);replace_literal_assignment('abstract',abstract)
section("heading('4.1 Ajuste", "blocks('La máscara final", "heading('4.1 Ajuste de tiempos y controles predictivos',True)\n"+block('El RMS final de entrenamiento es 0,793 s para 3D y 0,818 s para el control 1D, calculado en las posiciones estimadas por cada ajuste. Para la reserva se utiliza exclusivamente interpolación trilineal de los campos en las coordenadas exactas del catálogo, con hipocentros y orígenes fijos (Tabla 3). El 3D obtiene 1,551 s frente a 1,527 s del control 1D, una diferencia de +0,024 s con IC95 pareado [+0,007; +0,041] s. Las métricas robustas también favorecen al control. Los resultados por ronda y la evaluación histórica con redondeo se conservan únicamente como trazabilidad en el suplemento.')+"table('Tabla 3. Residuos de los mismos 747 eventos y 6837 lecturas reservadas, interpolados en coordenadas exactas. Todos los valores se expresan en segundos.', ['Modelo','RMS','Mediana |r|','P90 |r|','RMS recortado 95 %'], [['1D sin ajustes','1,602','0,942','2,396','1,246'],['Control 1D con relocalización y estáticas','1,527','0,903','2,273','1,192'],['3D con relocalización y estáticas','1,551','0,937','2,334','1,225']],[6.05,2.0,2.5,2.5,3.0])\n"+block('El control adicional con hipocentros de entrenamiento fijos y ajuste de orígenes y estaciones obtiene 1,502 s; su parametrización distinta impide atribuir causalmente la diferencia a un solo parámetro. Al retirar las estáticas del modelo 3D sin reajustarlo, el RMS reservado disminuye de 1,551 a 1,537 s; insertarlas en el 1D sin ajustes eleva el RMS de 1,602 a 1,632 s. Estas sustituciones no son nuevas inversiones. Demuestran que el efecto predictivo de las estáticas depende del ajuste conjunto y no respaldan una explicación única por elevación. Las cinco estaciones exclusivas de reserva reciben corrección cero en los controles independientes.'))
# Transfer explanatory medians to a table note.
section("blocks('La Tabla 5 se verificó", "heading('4.4 Cortes",block('Nota de la Tabla 5. La mediana superficial coincide con 5,31 km/s, pero solo 30 de los 1232 nodos activos conservan exactamente la velocidad inicial. Las medianas de 160 y 180 km son 8,2593 km/s a la precisión mostrada, con 406 y 119 nodos activos; esa igualdad numérica no implica igualdad física de los niveles.'))
# Replace the linear demonstration in the main figure with nonlinear recovery.
start=s.index("heading('4.5 Resolución lineal")
end=s.index("blocks('''El mayor índice",start) if "blocks('''El mayor índice" in s[start:] else s.index("blocks('El mayor índice",start)
s=s[:start]+"heading('4.5 Recuperación no lineal y clasificación espacial',True)\n"+block('La Figura 6 muestra el resultado principal de recuperación: los dos dameros no lineales generados a 5 km e invertidos a 10 km, con relocalización y estáticas libres. Los paneles comparan la anomalía verdadera agregada a las celdas de inversión y la estimada sobre la misma máscara activa. La Tabla 8 presenta los valores sobre el volumen completo. El ensayo lineal anterior, de correlación 0,557 y error relativo 0,833, reutiliza el Jacobiano final; se conserva como diagnóstico auxiliar en el suplemento y no como evidencia principal de resolución.')+"figure('Figura_6_sinteticos_no_lineales.png','Figura 6. Recuperación no lineal de dameros de ±3 % (fila superior) y ±8 % (inferior), en cortes a 60 km. El corte de 120 km se conserva en el suplemento S4. Se comparan referencia agregada y resultado 3D en las mismas celdas activas, con escala común de −16 a +16 % respecto al modelo 1D. Las correlaciones volumétricas son 0,044 y 0,095. La blancura de la referencia refleja la escala común; no ausencia de perturbación. La generación usa campos de tiempos a 5 km y la inversión recalcula campos y Jacobianos a 10 km en cada ronda. Ambos usan la misma familia FSM de primer orden.')\n\n"+s[end:]
s=s.replace('Los niveles abarcan el entorno del corte de 80 km presentado en la Figura 6 y permiten visualizar la dependencia con la profundidad.','Los niveles permiten visualizar la dependencia del bisector con la profundidad.')
depth_rows=[]
for r in A['depth_holdout']:
    label=str(r['depth_min_km'])+('–<' if r['depth_max_km']<180 else '–')+str(r['depth_max_km'])
    depth_rows.append([label,str(r['events']),str(r['picks']),*[fmt(r[n+'_rms_s'],4) for n in ['initial_1d','control_1d','final_3d']]])
section("heading('4.6 Evaluación", "heading('4.7 Convergencia", "heading('4.6 Reserva por profundidad',True)\n"+block('La Tabla 6 desglosa la misma reserva mediante interpolación exacta e incluye el control 1D. En la banda superficial el RMS del 3D es menor que el del control; en las otras tres bandas es mayor. Estos desgloses son descriptivos, sin selección de parámetros ni pruebas de significación por banda. La mejora frente al perfil sin ajustes no equivale a una mejora frente al control con relocalización y estáticas.')+'table('+repr('Tabla 6. RMS reservado por profundidad de catálogo, con interpolación trilineal en coordenadas exactas y orígenes fijos.')+','+repr(['Profundidad (km)','Eventos','P','Inicial 1D (s)','Control 1D (s)','Final 3D (s)'])+','+repr(depth_rows)+',[3.45,1.55,1.55,3.15,3.15,3.15])\n')
